SELECT ?point ?class ?ts WHERE {
  ?z a brick:Zone ; brick:hasIdentifier "Perimeter_ZN_2" .
  ?point ref:hasTimeseriesId ?ts ;
         brick:measuredValue ?z .
  ?point ?class .
}

SELECT ?s WHERE {
  ?s a brick:Zone .
  ?s brick:hasIdentifier ?id .
  FILTER (CONTAINS(LCASE(?id), "perimeter"))
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
}

